function heldItem(id){const uid=state.equipment[id];const instance=state.inventory.find(i=>i.uid===uid);return instance?itemDefs.find(d=>d.key===instance.key):null}
function rollLoot(random=Math.random){const n=random()*100;let rarity=n<55?'common':n<83?'rare':n<97?'epic':'legendary';const pool=itemDefs.filter(i=>i.rarity===rarity);return pool[Math.min(pool.length-1,Math.floor(random()*pool.length))]}
function grantLoot(def){const item={uid:globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2),key:def.key};state.inventory.push(item);save();return item}
function equipItem(uid,id){id=Number(id);if(!state.owned.includes(id))return;const instance=state.inventory.find(i=>i.uid===uid);if(!instance)return;if(run?.active||battle&&!battle.over)return toast('Change les objets au camp, avant le combat.');for(const k of Object.keys(state.equipment))if(state.equipment[k]===uid)delete state.equipment[k];state.equipment[id]=uid;save();inventoryPage();toast(`${nm(id)} porte maintenant ${itemDefs.find(d=>d.key===instance.key).name}.`)}
function unequipItem(id){if(run?.active||battle&&!battle.over)return toast('Attends la fin du combat.');delete state.equipment[id];save();inventoryPage()}
function inventoryPage(){root.innerHTML=head('LE SAC DU DRESSEUR','Objets & équipements','Un objet tenu par Pokémon. Les bonus s’appliquent en survie et dans la tour.')+`<div class="rarity-legend">${Object.entries(rarityInfo).map(([k,v])=>`<span style="color:${v.color}">◆ ${v.label} · ${v.chance} %</span>`).join('')}</div><div class="equipment-slots">${state.owned.map(id=>{const held=heldItem(id);return `<div class="held-slot">${image(id)}<strong>${nm(id)}</strong><small>${held?held.name:'Aucun objet tenu'}</small>${held?`<button onclick="unequipItem(${id})">Retirer</button>`:''}</div>`}).join('')}</div><h2>Ton sac · ${state.inventory.length} objets</h2><div class="loot-grid">${state.inventory.map((instance,index)=>{const d=itemDefs.find(i=>i.key===instance.key),who=Object.keys(state.equipment).find(k=>state.equipment[k]===instance.uid);if(!d)return '';return `<article class="loot-card ${d.rarity}"><span class="loot-icon">${itemMarkup(d)}</span><small>${rarityInfo[d.rarity].label}</small><h3>${d.name}</h3><p>${d.desc}</p>${who?`<p class="equipped">Équipé sur ${nm(+who)}</p>`:''}<label>Donner à<select id="equip-${index}" aria-label="Pokémon pour ${d.name}">${state.owned.map(id=>`<option value="${id}">${nm(id)}</option>`).join('')}</select></label><button onclick="equipItem('${instance.uid}',document.getElementById('equip-${index}').value)">Équiper</button></article>`}).join('')||'<div class="card empty-bag"><h2>Ton sac attend ses trésors…</h2><p>Explore les clairières. Approche-toi d’un coffre, puis appuie sur E ou sur Ouvrir.</p><button class="primary" onclick="nav(\'survival\')">Partir en exploration</button></div>'}</div>`}
const originalNav=nav;
nav=function(p){if(p==='inventory'){if(run?.active){finishRun();return}cancelAnimationFrame(anim);page=p;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#crumb').textContent='Sac & objets';document.body.dataset.page=p;inventoryPage();wallet();return}document.body.dataset.page=p;originalNav(p);state.owned.forEach(id=>ensurePmd(id))};
function starterModal(){dialog(`<div class="starter-intro"><span class="eyebrow">BIENVENUE DANS LA TOUR INFERNALE</span><h2>Ton aventure commence ici !</h2><p>Choisis ton tout premier Pokémon.<br>Il t’accompagnera dans la forêt et face aux gardiens de la tour.</p></div><div class="tabs starter-tabs">${regions.map((r,i)=>`<button class="${i===0?'active':''}" onclick="starterRegion(${i});document.querySelectorAll('.starter-tabs button').forEach((b,j)=>b.classList.toggle('active',j===${i}))">${r}</button>`).join('')}</div><div class="grid starter-grid" id="starterGrid">${cards([...starters[0],25,133],'chooseStarter')}</div><p class="help starter-hint">27 starters · 9 régions · Pikachu & Évoli aussi disponibles</p>`);modal.classList.add('starter-modal');const close=modal.querySelector('.close');if(close)close.hidden=true;modal.oncancel=e=>{if(!state.starter)e.preventDefault()}}
const originalChooseStarter=chooseStarter;
chooseStarter=function(id){if(![...starters.flat(),25,133].includes(id))return;originalChooseStarter(id);modal.classList.remove('starter-modal');modal.oncancel=null};
function homePage(){root.innerHTML=`<section class="hub"><div class="camp-card pixel-panel"><small>LE CAMP DES DRESSEURS</small><h3>La forêt te réserve des surprises !</h3><p>Des coffres cachés, des objets rares et des Pokémon à rencontrer.</p><button onclick="nav('survival')">Explorer la forêt →</button><div class="camp-row"><span>Étage atteint</span><strong>${String(state.floor).padStart(2,'0')}</strong></div><div class="camp-row"><span>Pokémon</span><strong>${state.owned.length} / 1025</strong></div><div class="camp-row"><span>Objets trouvés</span><strong>${state.inventory.length}</strong></div></div><div class="hub-center"><span class="hub-kicker">UNE AVENTURE ENTRE AMIS</span><h1>La Tour<br><em>Infernale</em></h1><div class="title-sub">LES GARDIENS DU SOMMET</div><button class="partner-card" onclick="${state.starter?'nav(\'team\')':'starterModal()'}"><canvas id="partner-preview" width="180" height="140"></canvas><strong>${state.starter?nm(state.starter):'Ton aventure t’attend'}</strong><small>${state.starter?'Ton premier partenaire':'Choisis ton premier Pokémon'}</small></button><div class="hub-actions"><button class="primary" onclick="${state.starter?'startBattle()':'starterModal()'}">⚔ Entrer dans la tour</button><button onclick="nav('survival')">✦ Mode survie</button></div><p class="hub-note">Un Pokémon en survie · Une équipe de six dans la tour</p></div><div class="camp-tip pixel-panel"><span>✦ ASTUCE D’EXPLORATION</span><p>Un coffre en vue ? Approche-toi et appuie sur <kbd>E</kbd>. Son trésor peut changer ton aventure.</p></div></section>`;startPartnerPreview()}
function startPartnerPreview(){const c=$('#partner-preview');if(!c)return;const ctx=c.getContext('2d');const id=state.starter||4;let raf;function draw(t){if(!c.isConnected){cancelAnimationFrame(raf);return}ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,180,140);ctx.fillStyle='#07172580';ctx.beginPath();ctx.ellipse(90,114,42,10,0,0,7);ctx.fill();drawMon(ctx,id,90,79,2.7,'Idle',0,t/1000);raf=requestAnimationFrame(draw)}raf=requestAnimationFrame(draw)}
const pmdImages={};
function assetImage(url){if(!pmdImages[url]){const im=new Image();im.crossOrigin='anonymous';im.src=url;pmdImages[url]=im}return pmdImages[url]}
function drawMon(ctx,id,x,y,scale=1,kind='Idle',direction=0,time=0){if(!window.PMD_DATA?.[id])ensurePmd(id);const set=window.PMD_DATA?.[id],data=set?.[kind]||set?.Idle;if(data){const mode=set[kind]?kind:'Idle',im=assetImage(set.remote?set[mode].url:`assets/pmd/${id}/${mode}.png`);if(im.complete&&im.naturalWidth){const frame=Math.floor(time*(kind==='Walk'?10:kind==='Attack'?13:5))%data.frames,row=Math.min(data.rows-1,direction);ctx.drawImage(im,frame*data.w,row*data.h,data.w,data.h,Math.round(x-data.w*scale/2),Math.round(y-data.h*scale/2),data.w*scale,data.h*scale);return}}const im=img(id);if(im.complete&&im.naturalWidth)ctx.drawImage(im,x-24*scale,y-24*scale,48*scale,48*scale)}
function directionFor(dx,dy){if(!dx&&!dy)return 0;const angle=Math.atan2(dy,dx);return [2,3,4,5,6,7,0,1][Math.round((angle+Math.PI)/(Math.PI/4))%8]}
const tileCache={};function noise(x,y){let n=(x*374761393+y*668265263)^0x9e3779b9;n=Math.imul(n^(n>>>13),1274126177);return((n^(n>>>16))>>>0)/4294967296}
function grassTile(index,path=false){const key=index+'-'+path;if(tileCache[key])return tileCache[key];const c=document.createElement('canvas');c.width=c.height=24;const x=c.getContext('2d');x.fillStyle=path?'#887448':['#437439','#47793a','#467637','#497c3b'][index%4];x.fillRect(0,0,24,24);for(let i=0;i<72;i++){const px=Math.floor(noise(i,index)*24),py=Math.floor(noise(index,i+7)*24);x.fillStyle=(path?['#9c8955','#75643e','#aa9560','#5f6338']:['#386830','#548641','#5b8d45','#3b6c32','#65924a'])[i%(path?4:5)];x.fillRect(px,py,i%3?2:1,1+(i%2))}tileCache[key]=c;return c}
function drawTree(c,x,y,s=1){c.save();c.translate(Math.round(x),Math.round(y));c.scale(s,s);const rect=(color,a,b,w,h)=>{c.fillStyle=color;c.fillRect(a,b,w,h)};rect('#173b27',-23,-12,48,15);rect('#173b27',-30,-31,58,23);rect('#173b27',-22,-49,44,22);rect('#173b27',-12,-61,24,18);rect('#744d2c',-6,-8,13,25);rect('#a17a43',-2,-7,5,23);rect('#295d32',-25,-33,47,28);rect('#2d6633',-18,-50,34,26);rect('#357535',-9,-60,18,20);rect('#47843b',-16,-42,25,18);rect('#599448',-7,-52,12,10);rect('#438039',-22,-25,35,15);rect('#61954a',-13,-31,18,8);rect('#1f4e2d',12,-31,10,22);rect('#25572e',-18,-8,38,6);for(let i=0;i<15;i++)rect(i%3?'#377236':'#6c9d50',-20+Math.floor(noise(i,2)*39),-47+Math.floor(noise(i,3)*39),4,3);c.restore()}
function drawRock(c,x,y){c.fillStyle='#334c3b';c.fillRect(x-13,y-7,29,16);c.fillStyle='#8d9b7e';c.fillRect(x-11,y-13,23,16);c.fillStyle='#a8af91';c.fillRect(x-5,y-16,14,7);c.fillStyle='#64765f';c.fillRect(x+8,y-7,6,13)}
function drawChest(c,x,y,opened=false,rare=false,time=0){c.save();c.translate(Math.round(x),Math.round(y));if(!opened){c.fillStyle=rare?'#a26cd4':'#f5d469';c.globalAlpha=.12+Math.sin(time*3)*.05;c.fillRect(-23,-22,46,40);c.globalAlpha=1}c.fillStyle='#291a20';c.fillRect(-17,-12,34,26);c.fillStyle=opened?'#755232':'#a36636';c.fillRect(-14,-10,28,22);c.fillStyle=rare?'#ab80d4':'#e7bf60';c.fillRect(-14,-3,28,3);c.fillRect(-12,-10,3,22);c.fillRect(9,-10,3,22);c.fillStyle='#e4c57c';c.fillRect(-3,-3,6,8);c.fillStyle='#593a21';c.fillRect(-1,0,2,3);c.fillStyle=opened?'#241c1c':'#c48a4c';c.fillRect(-11,-9,22,5);if(opened){c.fillStyle='#312127';c.fillRect(-11,-13,22,8);c.fillStyle='#ad7b44';c.fillRect(-14,-19,28,6)}else if(Math.sin(time*2+x)>.5){c.fillStyle='#fff5bd';c.fillRect(21,-24,2,8);c.fillRect(18,-21,8,2)}c.restore()}
function drawTerrain(ctx,cx,cy,w,h,trees=true){ctx.imageSmoothingEnabled=false;ctx.fillStyle='#47793a';ctx.fillRect(0,0,w,h);const sx=Math.floor(cx/24),sy=Math.floor(cy/24);for(let ty=sy;ty<sy+Math.ceil(h/24)+1;ty++)for(let tx=sx;tx<sx+Math.ceil(w/24)+1;tx++){const path=Math.abs((ty*24)-(Math.sin(tx*.11)*100+WORLD_SIZE/2))<40;ctx.drawImage(grassTile(Math.floor(noise(tx,ty)*8),path),tx*24-cx,ty*24-cy);const n=noise(tx+33,ty+17);if(n>.97&&!path){ctx.fillStyle=n>.985?'#e4dba4':'#e5a6a7';ctx.fillRect(tx*24-cx+10,ty*24-cy+12,3,3);ctx.fillStyle='#7db853';ctx.fillRect(tx*24-cx+11,ty*24-cy+15,1,4)}}if(trees){let decorations=[];for(let y=Math.floor((cy-100)/96);y<Math.ceil((cy+h+100)/96);y++)for(let x=Math.floor((cx-100)/96);x<Math.ceil((cx+w+100)/96);x++){const n=noise(x+50,y+90),xx=x*96+noise(x,y)*44,yy=y*96+noise(y,x)*40;if(n>.66&&Math.hypot(xx-WORLD_SIZE/2,yy-WORLD_SIZE/2)>125)decorations.push({x:xx-cx,y:yy-cy,n})}decorations.sort((a,b)=>a.y-b.y).forEach(d=>d.n>.93?drawRock(ctx,d.x,d.y):drawTree(ctx,d.x,d.y,1+noise(d.x,d.y)*.25))}}
let bgFrame=0;function initWorldBackground(){let c=$('#world-background');if(!c){c=document.createElement('canvas');c.id='world-background';document.body.prepend(c)}const ctx=c.getContext('2d');let last=0;const mons=[{id:54,x:.38,y:.24},{id:7,x:.61,y:.68},{id:39,x:.48,y:.72},{id:35,x:.22,y:.61},{id:143,x:.78,y:.85},{id:25,x:.70,y:.24},{id:4,x:.38,y:.54},{id:1,x:.18,y:.83}];function draw(t){bgFrame=requestAnimationFrame(draw);if(document.hidden||run?.active||t-last<80)return;last=t;const w=Math.ceil(innerWidth/2),h=Math.ceil(innerHeight/2);if(c.width!==w||c.height!==h){c.width=w;c.height=h}const cx=WORLD_SIZE/2-w/2,cy=WORLD_SIZE/2-h/2;drawTerrain(ctx,cx,cy,w,h);for(const m of mons)drawMon(ctx,m.id,m.x*w,m.y*h,1.65,'Idle',0,t/1000);drawChest(ctx,w*.77,h*.55,false,true,t/1000);ctx.fillStyle='#102b1b';ctx.fillRect(w*.45,h*.12,38,60);ctx.fillStyle='#78745b';ctx.fillRect(w*.45-4,h*.12-3,46,12);ctx.fillStyle='#a39c79';for(let k=0;k<5;k++)ctx.fillRect(w*.45-4+k*10,h*.12-11,6,11);ctx.fillStyle='#c7a36b';ctx.fillRect(w*.45+13,h*.12+12,10,12);ctx.fillStyle='#111c1c';ctx.fillRect(w*.45+12,h*.12+38,14,22)}bgFrame=requestAnimationFrame(draw)}
function survivalPage(){if(!requireStarter())return;root.innerHTML=head('LES CLAIRIÈRES SAUVAGES','Mode survie','Explore une vaste forêt, résiste aux vagues et trouve des coffres cachés.','1 POKÉMON · EXPLORATION')+`<section class="card"><h2>Ton unique partenaire</h2><div class="grid">${cards(state.owned,'selectSurvivor',[state.survivor])}</div><h3>Région des tickets</h3><div class="tabs">${regions.map((r,i)=>`<button class="${region===i?'active':''}" onclick="region=${i};survivalPage()">${r}</button>`).join('')}</div><div class="survival-brief"><div><strong>✦ Explore</strong><p>Une carte de 6 144 × 6 144, une caméra qui te suit, une visibilité limitée.</p></div><div><strong>▣ Ouvre des coffres</strong><p>Approche-toi puis appuie sur E. Des objets communs à légendaires t’attendent.</p></div><div><strong>◈ Équipe tes Pokémon</strong><p>Les objets sont conservés. Équipe-les depuis le sac, avant ta prochaine partie.</p></div></div><p>${heldItem(state.survivor)?'Objet tenu : '+heldItem(state.survivor).name+' · '+heldItem(state.survivor).desc:'Aucun objet tenu. Tu trouveras ton premier coffre près du point de départ.'}</p><button class="primary" onclick="startRun()">Entrer dans la forêt →</button> <button onclick="nav('inventory')">Ouvrir le sac</button><p class="help">ZQSD / WASD / flèches · Glisser sur mobile · E : coffre · Échap : pause · 1 ticket / 20 s</p></section>`}
function startRun(){if(!requireStarter())return;const held=heldItem(state.survivor)||{},max=Math.round(100*(1+(held.hp||0)));run={active:true,pause:false,x:WORLD_SIZE/2,y:WORLD_SIZE/2,hp:max,max,time:0,kills:0,enemies:[],bullets:[],gems:[],effects:[],xp:0,level:1,next:5,power:Math.round(27*(1+(held.atk||0))),cadence:.62*(1-(held.cadence||0)),speed:138*(1+(held.speed||0)),def:held.def||0,regen:held.regen||0,spawn:2.5,shoot:0,reward:0,region,joy:null,dir:0,moving:false,attackUntil:0,chests:[],opened:0,loot:[],viewW:640,viewH:400,camera:{x:0,y:0},vision:215};for(let i=0;i<95;i++){let x,y;if(i===0){x=run.x+115;y=run.y+15}else if(i<14){const a=i*2.399;const rad=220+i*62;x=run.x+Math.cos(a)*rad;y=run.y+Math.sin(a)*rad}else{x=96+noise(i,17)*(WORLD_SIZE-192);y=96+noise(i,52)*(WORLD_SIZE-192)}run.chests.push({x,y,opened:false,rare:i%7===5})}root.innerHTML=head('EXPÉDITION · '+regions[region],'La forêt des murmures','Explore, esquive et rapporte les trésors de la forêt.')+`<div class="run-hud pixel-panel"><b id="runTime">00:00</b><span id="runHealth">♥ ${max}</span><span id="runLevel">Niv. 1</span><span id="runKills">0 K.O.</span><span id="runLoot">▣ 0</span><button aria-label="Pause" style="margin-left:auto" onclick="togglePause()">Ⅱ</button><button onclick="finishRun()">Extraire</button></div><div class="survival-stage"><canvas id="survive" width="640" height="400" aria-label="Carte de survie"></canvas><div class="world-label">FORÊT DES MURMURES <small id="coordinates"></small></div><button id="chestAction" class="chest-action" onclick="openNearbyChest()" hidden><kbd>E</kbd> Ouvrir le coffre</button><div id="runPause" class="pause-overlay" hidden><h2>PAUSE</h2><button onclick="togglePause()">Reprendre l’exploration</button></div><div class="xp-track"><div id="xp-fill"></div></div></div><p class="help">ZQSD / WASD / flèches · Glisser pour se déplacer · E / bouton : ouvrir un coffre · Échap : pause</p>`;const c=$('#survive');c.onpointerdown=e=>{c.setPointerCapture(e.pointerId);setPointer(e)};c.onpointermove=e=>{if(e.buttons)setPointer(e)};c.onpointerup=c.onpointercancel=()=>{if(run)run.joy=null};function setPointer(e){const rect=c.getBoundingClientRect();run.joy={x:(e.clientX-rect.left)/rect.width*run.viewW,y:(e.clientY-rect.top)/rect.height*run.viewH}}let last=performance.now();function frame(now){if(!run?.active)return;const dt=Math.min(.04,(now-last)/1000);last=now;if(!run.pause)updateRun(dt);if(run.active)drawRun(c);anim=requestAnimationFrame(frame)}anim=requestAnimationFrame(frame)}
function togglePause(){if(!run?.active||modal.open)return;run.pause=!run.pause;run.joy=null;const overlay=$('#runPause');if(overlay)overlay.hidden=!run.pause}
addEventListener('keydown',e=>{if((e.key.toLowerCase()==='e'||e.key==='Enter')&&run?.active&&!run.pause){e.preventDefault();openNearbyChest()}});
function nearestChest(){if(!run?.active)return null;let best=null,dist=62;for(const chest of run.chests){const d=Math.hypot(chest.x-run.x,chest.y-run.y);if(!chest.opened&&d<dist){best=chest;dist=d}}return best}
function openNearbyChest(){if(!run?.active||run.pause)return;const chest=nearestChest();if(!chest)return;chest.opened=true;run.opened++;const def=rollLoot();const item=grantLoot(def);run.loot.push(item.uid);run.pause=true;run.joy=null;run.lootModal=true;dialog(`<div class="chest-reveal ${def.rarity}"><span class="eyebrow">LE COFFRE S’OUVRE…</span><div class="loot-burst">${itemMarkup(def)}</div><span class="rarity-badge">${rarityInfo[def.rarity].label}</span><h2>${def.name}</h2><p>${def.desc}</p><p class="help">Ajouté à ton sac et sauvegardé immédiatement.<br>Tu pourras l’équiper sur un Pokémon au camp.</p><button class="primary" onclick="resumeFromChest()">Continuer l’exploration →</button></div>`)}
function resumeFromChest(){if(run?.active&&run.lootModal){run.lootModal=false;run.pause=false;run.joy=null}modal.close()}
modal.addEventListener('close',()=>{if(run?.active&&run.lootModal){run.lootModal=false;run.pause=false}});
function updateRun(dt){const r=run;if(!r?.active||r.pause)return;r.time+=dt;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.q||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.z||keys.arrowup?1:0);if(r.joy){dx=r.joy.x-r.viewW/2;dy=r.joy.y-r.viewH/2;if(Math.hypot(dx,dy)<12)dx=dy=0}r.moving=!!(dx||dy);if(r.moving){const len=Math.hypot(dx,dy)||1;r.dir=directionFor(dx,dy);r.x=Math.max(32,Math.min(WORLD_SIZE-32,r.x+dx/len*r.speed*dt));r.y=Math.max(32,Math.min(WORLD_SIZE-32,r.y+dy/len*r.speed*dt))}r.hp=Math.min(r.max,r.hp+r.regen*dt);r.spawn-=dt;if(r.spawn<=0&&r.enemies.length<140){r.spawn=Math.max(.22,1-r.time/240);const a=Math.random()*Math.PI*2,dist=270+Math.random()*80;const pool=[...starters[r.region],...[10,16,19,41,43,54,60,74,92,161,263].filter(id=>id>=bounds[r.region]&&id<bounds[r.region+1])];r.enemies.push({x:Math.max(16,Math.min(WORLD_SIZE-16,r.x+Math.cos(a)*dist)),y:Math.max(16,Math.min(WORLD_SIZE-16,r.y+Math.sin(a)*dist)),hp:35+r.time*.55,max:35+r.time*.55,id:pool[Math.floor(Math.random()*pool.length)],speed:28+r.time*.13,hit:0})}r.shoot-=dt;const inRange=r.enemies.filter(e=>Math.hypot(e.x-r.x,e.y-r.y)<r.vision);if(r.shoot<=0&&inRange.length){r.shoot=r.cadence;const e=inRange.reduce((a,b)=>Math.hypot(a.x-r.x,a.y-r.y)<Math.hypot(b.x-r.x,b.y-r.y)?a:b),len=Math.hypot(e.x-r.x,e.y-r.y)||1;const type=survivalType(state.survivor);r.bullets.push({x:r.x,y:r.y,dx:(e.x-r.x)/len*330,dy:(e.y-r.y)/len*330,life:.8,type,trail:[]});r.attackUntil=r.time+.25}for(const e of r.enemies){const dx=r.x-e.x,dy=r.y-e.y,l=Math.hypot(dx,dy)||1;e.dir=directionFor(dx,dy);e.x+=dx/l*e.speed*dt;e.y+=dy/l*e.speed*dt;e.hit=Math.max(0,e.hit-dt);if(l<19){r.hp-=19*dt/(1+r.def);r.hurtUntil=r.time+.12}}for(const b of r.bullets){b.trail.push({x:b.x,y:b.y});if(b.trail.length>5)b.trail.shift();b.x+=b.dx*dt;b.y+=b.dy*dt;b.life-=dt;for(const e of r.enemies)if(e.hp>0&&b.life>0&&Math.hypot(e.x-b.x,e.y-b.y)<19){e.hp-=r.power;e.hit=.18;b.life=0;r.effects.push({x:e.x,y:e.y,life:.35,max:.35,type:b.type,n:r.power});e.x+=b.dx*.035;e.y+=b.dy*.035;if(e.hp<=0){r.kills++;r.gems.push({x:e.x,y:e.y})}}}r.bullets=r.bullets.filter(b=>b.life>0);r.enemies=r.enemies.filter(e=>e.hp>0&&Math.hypot(e.x-r.x,e.y-r.y)<700);r.effects.forEach(e=>e.life-=dt);r.effects=r.effects.filter(e=>e.life>0);r.gems=r.gems.filter(g=>{const d=Math.hypot(g.x-r.x,g.y-r.y);if(d<60){g.x+=(r.x-g.x)*dt*7;g.y+=(r.y-g.y)*dt*7}if(d<15){r.xp++;return false}return true});if(r.gems.length>300)r.gems.splice(0,r.gems.length-300);if(r.hp<=0){finishRun();return}if(r.xp>=r.next){r.xp-=r.next;r.level++;r.next+=4;r.pause=true;dialog(`<h2>Niveau ${r.level} !</h2><p>Choisis ton amélioration pour cette expédition.</p><div class="level-up"><button onclick="upgrade('power')">✦ Puissance<br>+15 dégâts</button><button onclick="upgrade('cadence')">↯ Cadence<br>+20 %</button><button onclick="upgrade('speed')">➤ Vitesse<br>+20 %</button></div>`);modal.querySelector('.close').hidden=true;modal.oncancel=e=>e.preventDefault()}$('#runTime').textContent=`${String(Math.floor(r.time/60)).padStart(2,'0')}:${String(Math.floor(r.time%60)).padStart(2,'0')}`;$('#runHealth').textContent='♥ '+Math.ceil(r.hp)+'/'+r.max;$('#runLevel').textContent='Niv. '+r.level;$('#runKills').textContent=r.kills+' K.O.';$('#runLoot').textContent='▣ '+r.opened;$('#coordinates').textContent=Math.floor(r.x)+' · '+Math.floor(r.y);$('#chestAction').hidden=!nearestChest();$('#xp-fill').style.width=(r.xp/r.next*100)+'%'}
function survivalType(id){if([4,6,155,255,390,498,653,725,813,909].includes(id))return 'fire';if([7,158,258,393,501,656,728,816,912].includes(id))return 'water';if(id===25)return 'electric';if([1,152,252,387,495,650,722,810,906].includes(id))return 'grass';return 'psychic'}
const effectColors={fire:['#ff6a27','#ffd36b','#ffebae'],water:['#2c90e7','#83dcff','#e3ffff'],grass:['#58b83d','#b4eb61','#f0ff9b'],electric:['#ffd72a','#fff898','#ffffff'],psychic:['#b46ee8','#f8a6ff','#fff0ff'],ice:['#63cde7','#c1faff','#ffffff'],ghost:['#8060b9','#ba8df6','#ded1ff']};
function drawProjectile(ctx,b,cx,cy){const colors=effectColors[b.type]||effectColors.psychic;for(let i=0;i<(b.trail||[]).length;i++){const p=b.trail[i];ctx.globalAlpha=(i+1)/7;ctx.fillStyle=colors[0];ctx.fillRect(Math.round(p.x-cx)-3,Math.round(p.y-cy)-3,6,6)}ctx.globalAlpha=1;const x=Math.round(b.x-cx),y=Math.round(b.y-cy);ctx.fillStyle=colors[0];ctx.fillRect(x-5,y-5,10,10);ctx.fillStyle=colors[1];ctx.fillRect(x-3,y-4,6,8);ctx.fillStyle=colors[2];ctx.fillRect(x-2,y-2,4,4);if(b.type==='grass'){ctx.fillStyle=colors[0];ctx.fillRect(x-8,y-1,4,3);ctx.fillRect(x+4,y-5,4,3)}if(b.type==='electric'){ctx.fillStyle=colors[2];ctx.fillRect(x-8,y-5,4,2);ctx.fillRect(x+5,y+4,4,2)}}
function drawRun(c){const ctx=c.getContext('2d'),r=run;if(!r?.active)return;const w=r.viewW,h=r.viewH,cx=Math.floor(Math.max(0,Math.min(WORLD_SIZE-w,r.x-w/2))),cy=Math.floor(Math.max(0,Math.min(WORLD_SIZE-h,r.y-h/2)));r.camera={x:cx,y:cy};ctx.imageSmoothingEnabled=false;drawTerrain(ctx,cx,cy,w,h);for(const chest of r.chests)if(Math.abs(chest.x-r.x)<w&&Math.abs(chest.y-r.y)<h)drawChest(ctx,chest.x-cx,chest.y-cy,chest.opened,chest.rare,r.time);for(const g of r.gems){ctx.fillStyle='#163959';ctx.fillRect(g.x-cx-4,g.y-cy-5,8,9);ctx.fillStyle='#6cdae8';ctx.fillRect(g.x-cx-3,g.y-cy-4,5,7);ctx.fillStyle='#d5ffff';ctx.fillRect(g.x-cx-2,g.y-cy-4,2,3)}const chars=[...r.enemies.map(e=>({...e,enemy:true})),{x:r.x,y:r.y,id:state.survivor,dir:r.dir,player:true}].sort((a,b)=>a.y-b.y);for(const e of chars){if(Math.abs(e.x-r.x)>w||Math.abs(e.y-r.y)>h)continue;ctx.fillStyle='#12261e70';ctx.beginPath();ctx.ellipse(e.x-cx,e.y-cy+15,e.player?16:13,5,0,0,7);ctx.fill();if(e.player){ctx.strokeStyle='#e9d88b';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(e.x-cx,e.y-cy+14,19,7,0,0,7);ctx.stroke()}ctx.globalAlpha=(e.hit>0||e.player&&r.hurtUntil>r.time)?.55:1;drawMon(ctx,e.id,e.x-cx,e.y-cy,1.35,e.player?(r.attackUntil>r.time?'Attack':r.moving?'Walk':'Idle'):'Walk',e.dir||0,r.time);ctx.globalAlpha=1;if(e.enemy&&e.hp<e.max){ctx.fillStyle='#203025';ctx.fillRect(e.x-cx-14,e.y-cy-24,28,3);ctx.fillStyle='#e59574';ctx.fillRect(e.x-cx-14,e.y-cy-24,28*e.hp/e.max,3)}}for(const b of r.bullets)drawProjectile(ctx,b,cx,cy);for(const fx of r.effects){const t=1-fx.life/fx.max,colors=effectColors[fx.type]||effectColors.psychic;ctx.fillStyle=colors[1];ctx.globalAlpha=1-t;for(let i=0;i<8;i++){const a=i*Math.PI/4;ctx.fillRect(Math.round(fx.x-cx+Math.cos(a)*t*22),Math.round(fx.y-cy+Math.sin(a)*t*22),3,3)}ctx.globalAlpha=1;ctx.fillStyle='#fff3bc';ctx.font='12px Pixelify Sans,monospace';ctx.textAlign='center';ctx.fillText('−'+fx.n,fx.x-cx,fx.y-cy-25-t*18)}const px=r.x-cx,py=r.y-cy;ctx.save();const fog=ctx.createRadialGradient(px,py,r.vision*.49,px,py,r.vision);fog.addColorStop(0,'rgba(6,19,16,0)');fog.addColorStop(.68,'rgba(5,18,15,.25)');fog.addColorStop(1,'rgba(4,13,12,.98)');ctx.fillStyle=fog;ctx.fillRect(0,0,w,h);ctx.restore();if(r.pause&&!modal.open){$('#runPause').hidden=false}else $('#runPause').hidden=true;if(nearestChest()){ctx.font='11px Pixelify Sans,monospace';ctx.fillStyle='#ffe39b';ctx.textAlign='center';ctx.fillText('E · OUVRIR',nearestChest().x-cx,nearestChest().y-cy-27)}}
function upgrade(type){if(!run?.active)return;if(type==='power')run.power+=15;if(type==='cadence')run.cadence=Math.max(.12,run.cadence*.8);if(type==='speed')run.speed*=1.2;run.pause=false;modal.oncancel=null;modal.close()}
function finishRun(){if(!run?.active)return;run.active=false;cancelAnimationFrame(anim);const tickets=Math.floor(run.time/20);state.tickets[run.region]+=tickets;state.coins+=run.kills;state.kills+=run.kills;state.runs++;save();if(modal.open)modal.close();modal.oncancel=null;root.innerHTML=head('EXPÉDITION TERMINÉE','De retour au camp',`${Math.floor(run.time)} secondes · ${run.kills} éliminations · ${run.opened||0} coffres ouverts`)+`<div class="card result"><h2>Les trésors de l’expédition</h2>${image(state.survivor)}<h1>+${tickets} tickets ${regions[run.region]}</h1><p>+${run.kills} fragments · ${(run.loot||[]).length} objets conservés dans le sac</p><div class="run-loot">${(run.loot||[]).map(uid=>{const item=state.inventory.find(i=>i.uid===uid),d=itemDefs.find(d=>d.key===item?.key);return d?`<span style="color:${rarityInfo[d.rarity].color}">${itemMarkup(d)} ${d.name}</span>`:''}).join('')}</div><button class="primary" onclick="nav('inventory')">Équiper mes trouvailles</button> <button onclick="nav('survival')">Repartir</button> <button onclick="nav('gacha')">Invoquer</button></div>`}
/* Battle visuals are driven by authoritative turn events, including in co-op. */
let battleVisualBusy=false,visualSerial=0;
function queueBattleFx(type,source,target,amount){battle.fx ||= [];battle.fx.push({type,source,target,amount});if(battle.fx.length>12)battle.fx.shift()}
const originalRenderBattle=renderBattle;
renderBattle=function(){if(battle?.turn===1&&!battle.fx?.length)visualSerial=0;originalRenderBattle();document.body.dataset.page='battle';if(!battle)return;const arena=$('.arena');if(!arena)return;const floor=document.createElement('canvas');floor.className='battle-floor';floor.width=640;floor.height=300;const x=floor.getContext('2d');drawTerrain(x,WORLD_SIZE/2-320,WORLD_SIZE/2-150,640,300,false);arena.prepend(floor);const mons=[{el:arena.querySelector('.boss-sprite'),id:battle.boss.id,boss:true},...battle.teams.map((t,i)=>({el:arena.querySelectorAll('.ally img')[i],id:t.mons[t.active].id,boss:false}))];for(const m of mons){if(!m.el)continue;const c=document.createElement('canvas');c.className=m.boss?'battle-mon boss-sprite':'battle-mon ally-sprite';c.width=160;c.height=160;const x=c.getContext('2d');m.el.replaceWith(c);let raf;function loop(t){if(!c.isConnected){cancelAnimationFrame(raf);return}x.imageSmoothingEnabled=false;x.clearRect(0,0,160,160);drawMon(x,m.id,80,80,Math.min(m.boss?3.5:3.2,window.PMD_DATA?.[m.id]?.Idle?145/Math.max(window.PMD_DATA[m.id].Idle.w,window.PMD_DATA[m.id].Idle.h):3),'Idle',m.boss?0:4,t/1000);raf=requestAnimationFrame(loop)}raf=requestAnimationFrame(loop)}const serial=battle.fxSerial||0;if(serial>visualSerial&&battle.fx?.length){visualSerial=serial;playBattleEffects(battle.fx.slice())}};
async function playBattleEffects(events){battleVisualBusy=true;const arena=$('.arena');if(!arena)return;arena.classList.add('animating');const controls=document.querySelectorAll('.moves button,.battle-team button');controls.forEach(b=>b.disabled=true);for(const e of events){if(!arena.isConnected)break;const source=e.source==='boss'?arena.querySelector('.boss-sprite'):arena.querySelectorAll('.ally')[e.source]?.querySelector('canvas'),target=e.target==='boss'?arena.querySelector('.boss-sprite'):arena.querySelectorAll('.ally')[e.target]?.querySelector('canvas');if(!source||!target)continue;const rect=arena.getBoundingClientRect(),a=source.getBoundingClientRect(),b=target.getBoundingClientRect();const fx=document.createElement('div');fx.className='attack-orb '+(effectColors[e.type]?e.type:'psychic');fx.style.left=(a.left+a.width/2-rect.left)+'px';fx.style.top=(a.top+a.height/2-rect.top)+'px';arena.append(fx);const label=document.createElement('div');label.className='attack-caption';label.textContent=(e.source==='boss'?'Le gardien':'Ton allié')+' attaque !';arena.append(label);source.classList.add('attack-lunge');const motion=fx.animate([{transform:'translate(-50%,-50%) scale(.5)',opacity:0},{transform:'translate(-50%,-50%) scale(1)',opacity:1,offset:.15},{transform:`translate(${b.left+b.width/2-a.left-a.width/2-8}px,${b.top+b.height/2-a.top-a.height/2-8}px) scale(1.4)`,opacity:1}],{duration:520,easing:'ease-in'});await motion.finished.catch(()=>{});source.classList.remove('attack-lunge');fx.remove();target.classList.add('hit-flash');const damage=document.createElement('span');damage.className='damage-number';damage.textContent=e.amount?'−'+e.amount:'Sans effet';damage.style.left=(b.left+b.width/2-rect.left)+'px';damage.style.top=(b.top-rect.top+30)+'px';arena.append(damage);await new Promise(r=>setTimeout(r,390));target.classList.remove('hit-flash');damage.remove();label.remove()}battleVisualBusy=false;arena.classList.remove('animating');if(arena.isConnected){const me=battle.teams.find(t=>t.pid===myId)||battle.teams[0];document.querySelectorAll('.moves button').forEach((b,i)=>b.disabled=!!(battle.over||battle.actions[myId]||!me.mons[me.active].moves[i]?.left||!me.mons[me.active].hp));document.querySelectorAll('.battle-team button').forEach((b,i)=>b.disabled=!!(battle.over||battle.actions[myId]||!me.mons[i]?.hp))}}
const originalAct=act;act=function(action){if(battleVisualBusy)return;originalAct(action)};
