async function ensurePmd(id){
 if(window.PMD_DATA?.[id]||pmdPending.has(id))return;
 pmdPending.set(id,true);
 const base='https://raw.githubusercontent.com/PMDCollab/SpriteCollab/master/sprite/'+String(id).padStart(4,'0')+'/';
 try{
  const response=await fetch(base+'AnimData.xml');if(!response.ok)return;
  const xml=new DOMParser().parseFromString(await response.text(),'text/xml');const all=[...xml.querySelectorAll('Anim')];const set={remote:true};
  for(const kind of ['Idle','Walk','Attack','Hurt']){
   let a=all.find(a=>a.querySelector('Name')?.textContent===kind);if(!a)continue;
   const name=a.querySelector('CopyOf')?.textContent||kind;if(name!==kind)a=all.find(a=>a.querySelector('Name')?.textContent===name);if(!a)continue;
   const w=+a.querySelector('FrameWidth')?.textContent,h=+a.querySelector('FrameHeight')?.textContent;if(!w||!h)continue;
   const im=assetImage(base+name+'-Anim.png');await new Promise(resolve=>{if(im.complete)return resolve();im.addEventListener('load',resolve,{once:true});im.addEventListener('error',resolve,{once:true})});if(!im.naturalWidth)continue;
   set[kind]={w,h,frames:Math.floor(im.naturalWidth/w),rows:Math.floor(im.naturalHeight/h),url:base+name+'-Anim.png'};
   if(kind==='Idle'){const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h,0,0,w,h);set.icon=c.toDataURL();document.querySelectorAll('img[data-mon="'+id+'"]').forEach(e=>e.src=set.icon)}
  }
  if(set.Idle)window.PMD_DATA[id]=set;
 }catch{}
}

function itemMarkup(def){return `<img class="item-sprite" src="assets/items/${def.key}.png" alt="${def.name}">`}
